// Clear any pending reconnection timer
if (this._lunaReconnectTimer) {
  clearTimeout(this._lunaReconnectTimer);
  this._lunaReconnectTimer = null;
}

// Cancel existing bridge prior to reconnecting
if (this.state.lunaBridge) {
  try {
    if (typeof this.state.lunaBridge.cancel === 'function') {
      this.state.lunaBridge.cancel();
    }
  } catch (_) {}
  this.state.lunaBridge = null;
}
if (typeof window !== 'undefined' && window._cinejoyLunaBridge) {
  try {
    if (typeof window._cinejoyLunaBridge.cancel === 'function') {
      window._cinejoyLunaBridge.cancel();
    }
  } catch (_) {}
  window._cinejoyLunaBridge = null;
}
if (this.state.lunaRequest) {
  try {
    if (typeof this.state.lunaRequest.cancel === 'function') {
      this.state.lunaRequest.cancel();
