    serviceApi = window.webOSTV.service;
  } else if (window.webOS && window.webOS.service && typeof window.webOS.service.request === 'function') {
    serviceApi = window.webOS.service;
  }
}

if (serviceApi) {
  try {
    console.log('[CinejoyApp] Registering Luna keepalive via webOSTV.service.request...');
    var req = serviceApi.request(serviceUri, {
      method: method,
      parameters: { subscribe: true },
      subscribe: true,
      resubscribe: true,
      onSuccess: function (res) {
        if (self.state.lunaRequest && self.state.lunaRequest !== req) {
          return;
        }
        self.handleKeepaliveSuccess(res);
      },
      onFailure: function (err) {
        if (self.state.lunaRequest && self.state.lunaRequest !== req) {
          return;
        }
        self.handleKeepaliveFailure(err);
      }
    });
