/**
 * scripts/verify-prod-ipk.js
 * Production IPK Package Verification Harness for com.cinejoy.tv
 *
 * Verifies dist/com.cinejoy.tv_1.0.0_all.ipk:
 *   1. File existence and minimum size
 *   2. Debian ar container format (debian-binary, control.tar.gz, data.tar.gz)
 *   3. Debian control metadata (Package: com.cinejoy.tv, Version: 1.0.0, Architecture: all)
 *   4. Data archive layout:
 *      - Application: usr/palm/applications/com.cinejoy.tv/
 *      - Package mapping: usr/palm/packages/com.cinejoy.tv/packageinfo.json
 *      - Service: usr/palm/services/com.cinejoy.tv.service/
 *      - Service assets: crush.wasm, http-client.js, resolver.js, hls-proxy.js, index.js, services.json
 *   5. Exact byte size check for crush.wasm (67,222 bytes)
 *   6. Manifest cross-validation (packageinfo.json ↔ appinfo.json ↔ services.json)
 *   7. SDK tooling compatibility (ares-package -I)
 *
 * Compatible with Node 12.22.2 through modern Node.js
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const defaultIpkPath = path.join(process.cwd(), 'dist', 'com.cinejoy.tv_1.0.0_all.ipk');
const targetIpk = process.argv[2] ? path.resolve(process.argv[2]) : defaultIpkPath;

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

function runCommand(cmd) {
  try {
    return execSync(cmd, { stdio: ['ignore', 'pipe', 'pipe'] }).toString('utf8');
  } catch (err) {
    throw new Error('Command failed: ' + cmd + '\n' + (err.stderr ? err.stderr.toString('utf8') : err.message));
  }
}

function runBufferCommand(cmd) {
  try {
    return execSync(cmd, { stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (err) {
    throw new Error('Command failed: ' + cmd + '\n' + (err.stderr ? err.stderr.toString('utf8') : err.message));
  }
}

function main() {
  console.log('\n' + C.bold + C.cyan + '================================================================' + C.reset);
  console.log(C.bold + C.cyan + '   CINEJOY PRODUCTION UNIFIED IPK VERIFICATION HARNESS         ' + C.reset);
  console.log(C.bold + C.cyan + '================================================================' + C.reset + '\n');

  console.log('Target IPK: ' + targetIpk);

  // Step 1: File Existence & Size
  process.stdout.write('  [1/7] Validating IPK file existence and minimum size ... ');
  assert(fs.existsSync(targetIpk), 'IPK file not found at: ' + targetIpk);
  const stat = fs.statSync(targetIpk);
  assert(stat.size > 50000, 'IPK file size suspiciously small: ' + stat.size + ' bytes');
  console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + (stat.size / 1024).toFixed(1) + ' KB)' + C.reset);

  // Step 2: Archive Container Format (Debian binary format)
  process.stdout.write('  [2/7] Verifying ar archive members (debian-binary, control, data) ... ');
  const arList = runCommand('ar -t "' + targetIpk + '"');
  const arMembers = arList.split('\n').map(function (s) { return s.trim(); }).filter(Boolean);
  assert(arMembers.indexOf('debian-binary') !== -1, 'Missing debian-binary member');
  assert(arMembers.indexOf('control.tar.gz') !== -1, 'Missing control.tar.gz member');
  assert(arMembers.indexOf('data.tar.gz') !== -1, 'Missing data.tar.gz member');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 3: Control Metadata Validation
  process.stdout.write('  [3/7] Inspecting control.tar.gz metadata ... ');
  const controlContent = runCommand('ar -p "' + targetIpk + '" control.tar.gz | tar -zxf - control -O');
  assert(controlContent.indexOf('Package: com.cinejoy.tv') !== -1, 'Missing Package: com.cinejoy.tv in control file');
  assert(controlContent.indexOf('Version: 1.0.0') !== -1, 'Missing Version: 1.0.0 in control file');
  assert(controlContent.indexOf('Architecture: all') !== -1, 'Expected Architecture: all in control file');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 4: Data Directory Layout Validation
  process.stdout.write('  [4/7] Checking required application and service paths in data.tar.gz ... ');
  const dataList = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -ztvf -');
  const expectedEntries = [
    'usr/palm/applications/com.cinejoy.tv/appinfo.json',
    'usr/palm/applications/com.cinejoy.tv/index.html',
    'usr/palm/applications/com.cinejoy.tv/js/config.js',
    'usr/palm/applications/com.cinejoy.tv/js/app.js',
    'usr/palm/packages/com.cinejoy.tv/packageinfo.json',
    'usr/palm/services/com.cinejoy.tv.service/services.json',
    'usr/palm/services/com.cinejoy.tv.service/package.json',
    'usr/palm/services/com.cinejoy.tv.service/index.js',
    'usr/palm/services/com.cinejoy.tv.service/resolver.js',
    'usr/palm/services/com.cinejoy.tv.service/hls-proxy.js',
    'usr/palm/services/com.cinejoy.tv.service/http-client.js',
    'usr/palm/services/com.cinejoy.tv.service/crush.wasm'
  ];

  for (let i = 0; i < expectedEntries.length; i++) {
    const entry = expectedEntries[i];
    assert(dataList.indexOf(entry) !== -1, 'Required entry missing from IPK: ' + entry);
  }
  console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + expectedEntries.length + '/' + expectedEntries.length + ' entries verified)' + C.reset);

  // Step 5: Exact crush.wasm Byte Size Check
  process.stdout.write('  [5/7] Verifying crush.wasm binary integrity (exactly 67,222 bytes) ... ');
  const wasmBuf = runBufferCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/crush.wasm -O');
  assert(wasmBuf.length === 67222, 'crush.wasm size mismatch: expected 67222 bytes, got ' + wasmBuf.length);
  // Verify WebAssembly magic header \0asm
  assert(wasmBuf[0] === 0x00 && wasmBuf[1] === 0x61 && wasmBuf[2] === 0x73 && wasmBuf[3] === 0x6d, 'Invalid WASM magic header in crush.wasm');
  console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(67,222 bytes, magic \\0asm valid)' + C.reset);

  // Step 6: Manifest Cross-Validation
  process.stdout.write('  [6/7] Cross-validating packageinfo.json, appinfo.json, services.json ... ');

  // Read packageinfo.json
  const pkgRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/packages/com.cinejoy.tv/packageinfo.json -O');
  const pkgJson = JSON.parse(pkgRaw);
  assert(pkgJson.id === 'com.cinejoy.tv', 'packageinfo.json id mismatch: ' + pkgJson.id);
  assert(pkgJson.app === 'com.cinejoy.tv', 'packageinfo.json app mismatch: ' + pkgJson.app);
  assert(Array.isArray(pkgJson.services) && pkgJson.services.indexOf('com.cinejoy.tv.service') !== -1, 'packageinfo.json missing service com.cinejoy.tv.service');

  // Read appinfo.json
  const appRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/applications/com.cinejoy.tv/appinfo.json -O');
  const appJson = JSON.parse(appRaw);
  assert(appJson.id === 'com.cinejoy.tv', 'appinfo.json id mismatch: ' + appJson.id);
  assert(appJson.version === '1.0.0', 'appinfo.json version mismatch: ' + appJson.version);
  assert(appJson.main === 'index.html', 'appinfo.json main mismatch: ' + appJson.main);
  assert(appJson.resolution === '1920x1080', 'appinfo.json resolution mismatch: ' + appJson.resolution);

  // Read services.json
  const srvRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/services.json -O');
  const srvJson = JSON.parse(srvRaw);
  assert(srvJson.id === 'com.cinejoy.tv.service', 'services.json id mismatch: ' + srvJson.id);
  assert(Array.isArray(srvJson.services) && srvJson.services[0].name === 'com.cinejoy.tv.service', 'services.json service registration mismatch');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 7: ares-package Inspection Compatibility
  process.stdout.write('  [7/7] Verifying SDK tooling compatibility (ares-package -I) ... ');
  const aresOutput = runCommand('ares-package -I "' + targetIpk + '"');
  assert(aresOutput.indexOf('< packageinfo.json >') !== -1, 'ares-package -I failed to parse packageinfo.json');
  assert(aresOutput.indexOf('< appinfo.json >') !== -1, 'ares-package -I failed to parse appinfo.json');
  assert(aresOutput.indexOf('< services.json >') !== -1, 'ares-package -I failed to parse services.json');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  console.log('\n' + C.green + C.bold + 'IPK VERIFICATION SUCCESS: ' + targetIpk + ' is fully compliant and ready for TV deployment!' + C.reset + '\n');
}

try {
  main();
  process.exit(0);
} catch (err) {
  console.error('\n' + C.red + C.bold + '✖ IPK VERIFICATION FAILED:' + C.reset + ' ' + err.message + '\n');
  process.exit(1);
}

