(async () => {
  const pages = await fetch("http://192.168.1.15:9998/json").then(r => r.json());
  const tvPage = pages.find(p => p.url && p.url.includes("com.cinejoy.tv"));
  if (!tvPage) { console.error("No TV page found!"); process.exit(1); }
  const ws = new WebSocket(tvPage.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let id = 1;
  function evalCode(expr) {
    return new Promise((resolve) => {
      const curId = id++;
      const handler = (evt) => {
        const msg = JSON.parse(evt.data);
        if (msg.id === curId) {
          ws.removeEventListener("message", handler);
          resolve(msg.result && msg.result.result ? msg.result.result.value : msg);
        }
      };
      ws.addEventListener("message", handler);
      ws.send(JSON.stringify({ id: curId, method: "Runtime.evaluate", params: { expression: expr, returnByValue: true, awaitPromise: true } }));
    });
  }

  const configProxy = await evalCode("window.CINEJOY_CONFIG.proxyBaseUrl");
  const appState = await evalCode("JSON.stringify({ subscribed: window.CinejoyApp.state.lunaSubscribed, activePort: window.CinejoyApp.state.activeProxyPort, uptime: window.CinejoyApp.state.lunaUptime })");
  const loopbackHealth = await evalCode("fetch(\"http://127.0.0.1:8088/health\").then(r => r.json())");

  console.log("Config proxyBaseUrl:", configProxy);
  console.log("App Luna State:", appState);
  console.log("Loopback Health from inside WAM:", loopbackHealth);
  ws.close();
})();'

